-- AD5 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD5.sql.
SELECT 'the address table holds the ten addresses' AS rule, (SELECT count(*) FROM desk.fadm_address) >= 10 AS ok
UNION ALL SELECT 'billing can receive (not send-only), noreply is send-only', (SELECT send_only FROM desk.fadm_mailbox WHERE local_part='billing') = false AND (SELECT send_only FROM desk.fadm_mailbox WHERE local_part='noreply') = true
UNION ALL SELECT 'support and priority can never be an address or a mailbox', NOT EXISTS (SELECT 1 FROM desk.fadm_mailbox WHERE local_part IN ('support','priority')) AND NOT EXISTS (SELECT 1 FROM desk.fadm_address WHERE local_part IN ('support','priority'))
UNION ALL SELECT 'the founder address is private and has no staff mailbox', (SELECT visibility FROM desk.fadm_address WHERE local_part='naumansherwani.founder') = 'private' AND NOT EXISTS (SELECT 1 FROM desk.fadm_mailbox WHERE local_part='naumansherwani.founder')
UNION ALL SELECT 'billing is restricted', (SELECT visibility FROM desk.fadm_address WHERE local_part='billing') = 'restricted'
UNION ALL SELECT 'postmaster, abuse and dmarc forward to resolved with a label', (SELECT count(*) FROM desk.fadm_address WHERE kind='forward' AND forward_to='resolved' AND label IS NOT NULL) = 3
UNION ALL SELECT 'the private guard trigger is on the mailbox table', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='desk.fadm_mailbox'::regclass AND tgname='fadm_mailbox_00private')
UNION ALL SELECT 'both AD5 tables have RLS enabled and forced', (SELECT count(*) FROM pg_class c JOIN pg_namespace s ON s.oid=c.relnamespace WHERE s.nspname='desk' AND c.relname IN ('fadm_address','fadm_mailbox_grant') AND c.relrowsecurity AND c.relforcerowsecurity) = 2
UNION ALL SELECT 'desk_app has no direct right on the AD5 tables', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid=c.relnamespace WHERE s.nspname='desk' AND c.relname IN ('fadm_address','fadm_mailbox_grant') AND (has_table_privilege('desk_app',c.oid,'SELECT') OR has_table_privilege('desk_app',c.oid,'INSERT') OR has_table_privilege('desk_app',c.oid,'UPDATE') OR has_table_privilege('desk_app',c.oid,'DELETE')))
UNION ALL SELECT 'the four AD5 doors are granted to desk_app', has_function_privilege('desk_app','desk.fadm_route_inbound(text)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_reply_from(text)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_mailbox_can_read(uuid,text)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_mailbox_grant_set(uuid,uuid,text,boolean,inet)','EXECUTE')
UNION ALL SELECT 'mailbox.grant is an action with an admin policy', EXISTS (SELECT 1 FROM desk.fadm_policy WHERE name='p_mailbox_grant' AND action='mailbox.grant')
UNION ALL SELECT 'all SECURITY DEFINER functions pin search_path', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid=p.pronamespace WHERE s.nspname='desk' AND p.prosecdef AND (p.proconfig IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')))
UNION ALL SELECT 'ledger hash chain still verifies', desk.fadm_ledger_verify();
